// 10. Floating Dock Icons: Tight 3D HD Renders
export const DockIcon = ({ tabId, active, size = 34 }) => {
  let imgSource = dockHomeImg;
  if (tabId === 'khata') imgSource = dockGrahakImg;
  else if (tabId === 'bill') imgSource = dockBillImg;
  else if (tabId === 'settings') imgSource = dockSettingsImg;

  return (
    <Image
      source={imgSource}
      style={{
        width: size,
        height: size,
        opacity: active ? 1 : 0.85,
      }}
      resizeMode="contain"
    />
  );
};

